        <h2>10 Early Warning Signs of Heart Disease</h2>

        <h3>1. Chest Pain, Pressure, Tightness, or Discomfort</h3>

        <p>
            Chest discomfort is one of the most important symptoms to recognize.
            Heart-related discomfort may feel like pressure, squeezing, heaviness,
            fullness, burning, or an uncomfortable sensation in the centre of the chest.
            It does not always feel like severe pain.
        </p>

        <p>
            Angina can occur when the heart muscle does not receive enough oxygen-rich
            blood. It may appear during physical activity or emotional stress and improve
            with rest. New, severe, persistent, or rest-related chest discomfort needs
            prompt medical attention.
        </p>

        <p>
            If chest discomfort does not go away after a few minutes, keeps returning,
            or occurs with shortness of breath, sweating, nausea, dizziness, or pain
            spreading to the arm, jaw, neck, back, or upper abdomen, seek emergency
            medical help immediately.
        </p>

        <p>
            Learn more about
            <a href="/heart-care/">heart care and cardiovascular conditions</a>
