        </p>

        <h3>2. Shortness of Breath During Routine Activities</h3>

        <p>
            Getting out of breath after intense exercise can be normal. New breathlessness
            during activities that were previously comfortable is different and should not
            automatically be blamed on age, stress, or low fitness.
        </p>

        <p>
            Heart conditions can affect how efficiently blood and oxygen are delivered around
            the body. Breathlessness may occur with coronary artery disease, heart failure,
            heart valve problems, or certain abnormal heart rhythms.
        </p>

        <p>
            Some people may also become breathless while lying down or wake up at night
            struggling to breathe. New or worsening breathlessness should be medically evaluated.
        </p>

        <div class="my-8 bg-[#328CCB]/10 p-6 rounded-xl">
            <p class="font-semibold text-gray-900 mb-2">Important:</p>

            <p class="text-gray-700">
                Shortness of breath can also be caused by lung conditions, anemia, anxiety,
                infections, and other health problems. A symptom alone cannot confirm a heart
                condition. The underlying cause needs professional assessment.
            </p>
        </div>

        <h3>3. Unusual or Persistent Fatigue</h3>

        <p>
            Everyone feels tired sometimes. However, unexplained fatigue that is new,
            persistent, or much stronger than usual can deserve attention, especially when
            it occurs with breathlessness, dizziness, chest discomfort, or reduced ability
            to perform normal activities.
        </p>

        <p>
            Fatigue can occur when the heart is not pumping blood effectively, but it is also
            associated with many other conditions. This makes the pattern and combination of
            symptoms important.
        </p>

        <p>
            Unusual tiredness or weakness can also occur during a heart attack, particularly
            in women. It may appear alongside shortness of breath, nausea, sweating, or back
            or jaw discomfort.
        </p>

        <h3>4. Fast, Pounding, or Irregular Heartbeat</h3>

        <p>
            Palpitations are the sensation of feeling your heartbeat. You may notice pounding,
            racing, fluttering, skipped beats, or an irregular rhythm in your chest.
        </p>

        <p>
            Palpitations can occur because of stress, caffeine, certain medicines, hormonal
            changes, or other non-cardiac causes. They can also occur with an arrhythmia,
            which is an abnormal heart rhythm.
        </p>

        <p>
            Pay particular attention if palpitations are frequent, last longer than usual,
            keep returning, or occur with dizziness, fainting, chest discomfort, or breathing
            difficulty. A medical assessment can help determine whether an abnormal rhythm
            is present.
        </p>

        <p>
            If you need specialist evaluation, learn more about consulting a
            <a href="/cardiologist/haryana/gurgaon/">cardiologist in Gurugram</a>.
        </p>

        <h3>5. Dizziness, Lightheadedness, or Fainting</h3>

        <p>
            Occasional dizziness can have many causes, including dehydration, low blood
            pressure, medicine effects, or standing up suddenly. Repeated dizziness,
            unexplained lightheadedness, or fainting can sometimes be associated with
            an abnormal heart rhythm or reduced blood flow.
        </p>

        <p>
            Fainting is especially important when it occurs during physical activity or
            together with chest discomfort, palpitations, or breathlessness. These combinations
            require prompt medical assessment.
        </p>

        <p>
            Do not try to diagnose the cause yourself. A healthcare professional may need
            to check your blood pressure, heart rhythm, medical history, and other possible causes.
        </p>

        <h3>6. Swelling in the Feet, Ankles, or Legs</h3>

        <p>
            Swelling in the lower legs can occur for several reasons, including prolonged
            standing, certain medicines, kidney problems, vein problems, and other conditions.
            Persistent or increasing swelling can also occur when the heart is not pumping
            blood effectively.
        </p>

        <p>
            Heart failure can cause fluid to build up in the body, which may lead to swelling
            in the feet, ankles, legs, or sometimes the abdomen. Swelling becomes more concerning
            when it occurs together with increasing breathlessness, fatigue, or rapid changes
            in body weight.
        </p>

        <p>
            If swelling is new, persistent, or getting worse, arrange a medical evaluation
            rather than assuming it is simply a result of sitting or standing for too long.
        </p>

        <h3>7. Pain or Discomfort in the Jaw, Neck, Back, Arms, or Shoulders</h3>

        <p>
            Heart-related discomfort does not always stay in the chest. During a heart attack,
            discomfort can spread to one or both arms, the shoulder, back, neck, jaw, or upper abdomen.
        </p>

        <p>
            This can be confusing because these symptoms may resemble muscle strain, acidity,
            dental problems, or other everyday conditions. Pain that appears with chest pressure,
            breathlessness, sweating, nausea, or dizziness needs urgent attention.
        </p>

        <p>
            Women can experience less typical heart attack symptoms, including discomfort in
            the back, shoulder, neck, jaw, or arm. The absence of severe chest pain should not
            automatically rule out a heart problem.
        </p>

        <h3>8. Nausea, Vomiting, or Indigestion-Like Discomfort</h3>

        <p>
            Nausea and indigestion are common and are often caused by digestive conditions.
            However, these symptoms can also occur during a heart attack, particularly when
            they appear suddenly or alongside other symptoms.
        </p>

        <p>
            Some people may feel a burning sensation, pressure, fullness, or discomfort that
            they mistake for acidity or indigestion. The risk of confusion is greater when
            classic chest pain is absent.
        </p>

        <p>
            If unexplained nausea or indigestion occurs with chest discomfort, breathlessness,
            cold sweating, dizziness, or pain in the jaw, back, shoulder, or arm, seek emergency
            medical help.
        </p>

        <h3>9. Sudden Cold Sweating Without an Obvious Reason</h3>

        <p>
            Sweating is a normal response to heat, exercise, anxiety, or illness. A sudden
            cold sweat without an obvious reason can be more concerning when it appears together
            with chest discomfort, shortness of breath, nausea, dizziness, or weakness.
        </p>

        <p>
            Cold sweating is one possible symptom accompanying a heart attack. It is not specific
            to heart disease, but the combination of symptoms can provide an important warning.
        </p>

        <div class="bg-red-50 border-l-4 border-red-500 p-6 my-8 rounded-xl">
            <p class="font-semibold text-gray-900 mb-2">
                Do not wait during a possible cardiac emergency
            </p>

            <p class="text-gray-700">
                If sudden sweating occurs with chest pressure or pain, severe breathlessness,
                fainting, or pain spreading to the arm, jaw, neck, back, or upper abdomen,
                seek emergency medical help immediately.
            </p>
        </div>

        <h3>10. Persistent Cough or Wheezing</h3>

        <p>
            A persistent cough is often caused by respiratory infections, allergies, asthma,
            or other lung conditions. However, ongoing coughing or wheezing can also occur
            when fluid builds up in the lungs because of heart failure.
        </p>

        <p>
            A cough accompanied by breathlessness, swelling in the legs, unusual fatigue,
            or difficulty breathing while lying down should be medically evaluated.
        </p>

        <p>
            Pink or frothy sputum together with severe breathing difficulty can indicate a
            serious condition requiring emergency care. Do not treat such symptoms only
            as a routine cough.
        </p>

        <h2>Why Can Heart Disease Symptoms Be Easy to Miss?</h2>

        <p>
            Heart disease can develop gradually, and symptoms may overlap with many other
            health problems. Fatigue can be blamed on poor sleep, breathlessness on low fitness,
            nausea on indigestion, and dizziness on dehydration.
        </p>

        <p>
            Some cardiovascular conditions can also remain without obvious symptoms until a
            major event occurs. Knowing your personal risk factors and discussing concerning
            changes with a healthcare professional are important parts of prevention.
        </p>

        <p>
            Early detection and management of cardiovascular disease can help reduce the impact
            of preventable risk factors. Tobacco use, unhealthy diet, physical inactivity,
            excess body weight, high blood pressure, diabetes, and abnormal cholesterol are
            among the factors associated with cardiovascular risk.
        </p>

        <h2>Heart Disease Symptoms in Women Can Be Different</h2>

        <p>
            Women can experience classic heart attack symptoms, including chest discomfort.
            However, they may also experience symptoms that are easier to mistake for another condition.
        </p>

        <ul class="list-disc pl-6 space-y-2 my-4">
            <li>Unusual or extreme tiredness</li>
            <li>Shortness of breath</li>
            <li>Nausea or vomiting</li>
            <li>Indigestion-like discomfort</li>
            <li>Pain or discomfort in the back, shoulder, neck, jaw, or arm</li>
            <li>Lightheadedness</li>
            <li>Cold sweating</li>
        </ul>

        <p>
            These symptoms do not mean that every episode is heart-related. However, sudden
            or unexplained symptoms, especially when several occur together, should not be dismissed.
        </p>

        <h2>Who Has a Higher Risk of Heart Disease?</h2>

        <p>
            Symptoms are only one part of the picture. Overall cardiovascular risk also depends
            on factors that may be present before symptoms appear.
        </p>

        <div class="overflow-x-auto my-8">
            <table class="w-full border-collapse border border-gray-200 text-left">
                <thead>
                    <tr class="bg-[#328CCB]">
                        <th class="border border-gray-200 px-4 py-3 font-bold" style="color:#ffffff;">
                            Risk factor
                        </th>
                        <th class="border border-gray-200 px-4 py-3 font-bold" style="color:#ffffff;">
                            Why it matters
                        </th>
                    </tr>
                </thead>

                <tbody>
                    <tr>
                        <td class="border border-gray-200 px-4 py-3 font-semibold">
                            High blood pressure
                        </td>
                        <td class="border border-gray-200 px-4 py-3">
                            Can place extra strain on the heart and blood vessels over time.
                        </td>
                    </tr>

                    <tr>
                        <td class="border border-gray-200 px-4 py-3 font-semibold">
                            High cholesterol
                        </td>
                        <td class="border border-gray-200 px-4 py-3">
                            Can contribute to plaque buildup in the arteries.
                        </td>
                    </tr>

                    <tr>
                        <td class="border border-gray-200 px-4 py-3 font-semibold">
                            Diabetes
                        </td>
                        <td class="border border-gray-200 px-4 py-3">
                            Raises the risk of cardiovascular disease and can affect blood vessels.
                        </td>
                    </tr>

                    <tr>
                        <td class="border border-gray-200 px-4 py-3 font-semibold">
                            Smoking or tobacco use
                        </td>
                        <td class="border border-gray-200 px-4 py-3">
                            Damages blood vessels and increases cardiovascular risk.
                        </td>
                    </tr>

                    <tr>
                        <td class="border border-gray-200 px-4 py-3 font-semibold">
                            Physical inactivity
                        </td>
                        <td class="border border-gray-200 px-4 py-3">
                            Can contribute to several cardiovascular risk factors.
                        </td>
                    </tr>

                    <tr>
                        <td class="border border-gray-200 px-4 py-3 font-semibold">
                            Overweight or obesity
                        </td>
                        <td class="border border-gray-200 px-4 py-3">
                            Can increase the risk of high blood pressure, diabetes, and cardiovascular disease.
                        </td>
                    </tr>

                    <tr>
                        <td class="border border-gray-200 px-4 py-3 font-semibold">
                            Family history
                        </td>
                        <td class="border border-gray-200 px-4 py-3">
                            Some inherited factors can increase cardiovascular risk.
                        </td>
                    </tr>
                </tbody>
            </table>
        </div>

        <p>
            Managing these factors can reduce cardiovascular risk. If you also have diabetes,
            read our guide to
            <a href="/blog/en/managing-diabetes-daily">managing diabetes in daily life</a>.
        </p>

        <h2>How Is Heart Disease Diagnosed?</h2>

        <p>
            There is no single test that diagnoses every type of heart disease. Evaluation
            depends on your symptoms, medical history, risk factors, physical examination,
            and the condition your doctor suspects.
        </p>

        <p>A healthcare professional may consider tests such as:</p>

        <ul class="list-disc pl-6 space-y-2 my-4">
            <li>
                <strong>Electrocardiogram (ECG):</strong>
                Records the electrical activity of the heart and can help identify certain
                rhythm problems and signs of heart injury.
            </li>

            <li>
                <strong>Blood tests:</strong>
                May help assess cholesterol, blood sugar, and other markers. Troponin testing
                is important when a heart attack is suspected.
            </li>

            <li>
                <strong>Echocardiogram:</strong>
                Uses ultrasound to examine the heart structure and pumping function.
            </li>

            <li>
                <strong>Stress testing:</strong>
                May be used in selected patients to assess how the heart responds to physical
                activity or medication-induced stress.
            </li>

            <li>
                <strong>CT-based imaging:</strong>
                May be recommended in selected cases to examine the heart or blood vessels.
            </li>

            <li>
                <strong>Holter or ambulatory monitoring:</strong>
                Can record the heart rhythm over a longer period when intermittent palpitations
                or rhythm problems are suspected.
            </li>
        </ul>

        <p>
            Depending on the situation, your doctor may recommend blood investigations through
            a <a href="/laboratory">medical laboratory</a> or imaging such as a
            <a href="/ct-scan">CT scan</a>.
        </p>

        <h2>When Should You Seek Emergency Medical Help?</h2>

        <p>
            Some heart symptoms should never be managed by waiting at home. A possible heart
            attack requires urgent medical evaluation because treatment is time-sensitive.
        </p>

        <div class="bg-red-50 border border-red-200 p-6 my-8 rounded-xl">
            <p class="font-semibold text-gray-900 mb-3">
                Seek emergency medical help immediately if you have:
            </p>

            <ul class="list-disc pl-6 space-y-2 text-gray-700">
                <li>Sudden chest pressure, squeezing, heaviness, or pain that does not go away</li>
                <li>Chest discomfort that returns or becomes worse</li>
                <li>Severe or sudden difficulty breathing</li>
                <li>Chest discomfort with cold sweating, nausea, dizziness, or fainting</li>
                <li>Pain or discomfort spreading to the arm, shoulder, jaw, neck, back, or upper abdomen</li>
                <li>Collapse or loss of consciousness</li>
            </ul>
        </div>

        <p>
            For patients in Gurugram, Akropolis Hospital provides
            <a href="/emergency">24/7 emergency care</a>. In a suspected cardiac emergency,
            seek immediate emergency medical assistance rather than waiting for a routine appointment.
        </p>

        <h2>What Can You Do to Protect Your Heart?</h2>

        <p>
            Knowing the symptoms is important, but prevention also matters. Many cardiovascular
            risk factors can be managed through lifestyle changes and appropriate medical care.
        </p>

        <ul class="list-disc pl-6 space-y-2 my-4">
            <li>Do not smoke or use tobacco products.</li>
            <li>Stay physically active according to your health and fitness level.</li>
            <li>Choose a balanced eating pattern with vegetables, fruits, whole grains, legumes, nuts, and appropriate sources of protein.</li>
            <li>Limit excess salt, added sugar, and foods high in saturated or trans fats.</li>
            <li>Maintain a healthy weight where appropriate.</li>
            <li>Monitor and manage blood pressure, cholesterol, and blood sugar.</li>
            <li>Take prescribed medicines as directed.</li>
            <li>Know your family history of heart disease.</li>
            <li>Attend recommended health checkups.</li>
            <li>Talk to a healthcare professional when you notice new or unexplained symptoms.</li>
        </ul>

        <p>
            Regular health assessments can help identify risk factors before they become major
            problems. You can also read our guide on the
            <a href="/blog/en/importance-of-regular-health-checkups">importance of regular health checkups</a>.
        </p>

        <div class="my-10 bg-[#328CCB]/10 p-8 rounded-2xl text-center">
            <p class="text-xl font-bold text-gray-900 mb-3">
                Concerned about a heart-related symptom?
            </p>

            <p class="text-gray-600 mb-6 max-w-2xl mx-auto">
                Do not ignore a new or unexplained symptom. Speak with a qualified healthcare
                professional to understand the possible cause and appropriate next steps.
            </p>

            <a href="/contact"
               class="inline-block bg-[#D66C43] px-8 py-3 rounded-full font-bold no-underline transition-all hover:bg-[#c55a36]"
               style="color:#ffffff !important; text-decoration:none !important;">
                Book a Cardiology Consultation
            </a>
        </div>

        <h2>When Should You See a Cardiologist?</h2>

        <p>
            Consider discussing symptoms with a doctor when they are persistent, recurrent,
            unexplained, or affecting your normal activities. A cardiology evaluation may be
            particularly important if you have cardiovascular risk factors or a family history
            of early heart disease.
        </p>

        <p>
            Recurring chest discomfort, unexplained breathlessness, frequent palpitations,
            repeated dizziness, unexplained fainting, or persistent swelling deserve medical
            attention even if they are not severe at the moment.
        </p>

        <p>
            At Akropolis Hospital, the
            <a href="/cardiology">Cardiology Department</a>
            provides evaluation and treatment for conditions including coronary artery disease,
            heart failure, arrhythmias, valve disorders, hypertension, and chest pain.
        </p>

        <h2>Conclusion</h2>

        <p>
            Heart disease can sometimes develop without obvious symptoms, while other cases
            produce warning signs that are easy to dismiss. Chest discomfort, breathlessness,
            unusual fatigue, palpitations, dizziness, swelling, pain outside the chest,
            digestive symptoms, cold sweating, and persistent cough can have different causes,
            but some may be associated with cardiovascular disease.
        </p>

        <p>
            The most important step is to pay attention to changes in your body. If symptoms
            are new, persistent, recurrent, or worsening, speak with a healthcare professional.
            If symptoms suggest a possible heart attack or another medical emergency, seek
            emergency care immediately.
        </p>

        <p>
            Early attention does not mean that every symptom is a heart problem. It means giving
            yourself the opportunity to identify a problem early and receive appropriate care
            when it is needed.
        </p>

